from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s.count('B') != t.count('B'):
        return -1

    start = s + "EE"
    target = t + "EE"

    if start == target:
        return 0

    N = n + 2
    q = deque([start])
    dist = {start: 0}

    while q:
        state = q.popleft()
        d = dist[state]
        h = state.find('E')

        for i in range(N - 1):
            if state[i] != 'E' and state[i + 1] != 'E':
                nxt = list(state)
                a, b = nxt[i], nxt[i + 1]

                nxt[i] = 'E'
                nxt[i + 1] = 'E'
                nxt[h] = a
                nxt[h + 1] = b

                new_state = ''.join(nxt)
                if new_state == target:
                    return d + 1

                if new_state not in dist:
                    dist[new_state] = d + 1
                    q.append(new_state)

    return -1

from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    ans = 10**30
    prev_or = set()

    for x in nums:
        cur_or = {x}

        for val in prev_or:
            cur_or.add(val | x)

        for val in cur_or:
            diff = abs(k - val)
            if diff < ans:
                ans = diff
                if ans == 0:
                    return 0

        prev_or = cur_or

    return ans

