from itertools import product
from typing import List, Tuple


def min_spanning_tree_mod_k(
    n: int, m: int, k: int, edges: List[Tuple[int, int, int]]
) -> int:
    # Convert to 0-indexed weights. -1 means the edge is absent.
    weight = [[-1] * n for _ in range(n)]
    for u, v, w in edges:
        u -= 1
        v -= 1
        weight[u][v] = w
        weight[v][u] = w

    # Prüfer sequences encode every labeled tree on n vertices exactly once.
    best = k

    for code in product(range(n), repeat=n - 2):
        deg = [1] * n
        for x in code:
            deg[x] += 1

        total = 0
        valid = True

        for x in code:
            leaf = 0
            while deg[leaf] != 1:
                leaf += 1

            w = weight[x][leaf]
            if w < 0:
                valid = False
                break

            total += w
            deg[x] -= 1
            deg[leaf] -= 1

        if not valid:
            continue

        first = -1
        second = -1
        for v in range(n):
            if deg[v] == 1:
                if first == -1:
                    first = v
                else:
                    second = v
                    break

        w = weight[first][second]
        if w < 0:
            continue

        total += w
        candidate = total % k
        if candidate < best:
            best = candidate

    return best

from typing import List, Optional
from itertools import permutations


def _inversion_count(perm) -> int:
    count = 0
    for i in range(len(perm)):
        for j in range(i + 1, len(perm)):
            if perm[i] > perm[j]:
                count += 1
    return count


def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    best = None

    for row_perm in permutations(range(H)):
        for col_perm in permutations(range(W)):
            if all(
                B[i][j] == A[row_perm[i]][col_perm[j]]
                for i in range(H)
                for j in range(W)
            ):
                operations = _inversion_count(row_perm) + _inversion_count(col_perm)
                if best is None or operations < best:
                    best = operations

    return best

